-- changeset JOBTRACKER:1795008487194 stripComments:false  logicalFilePath:feat/offer-search-result-views/jobtracker/views/ft_offer_search_results.sql
-- sqlcl_snapshot src/database/jobtracker/views/ft_offer_search_results.sql:null:3472ab3a8fc56658e7a63d6dc6b50c6904307460:create

create or replace force editionable view jobtracker.ft_offer_search_results (
    search_rank,
    external_id,
    title,
    description,
    created_at,
    updated_at,
    workplace_name,
    workplace_latitude,
    workplace_longitude,
    workplace_postal_code,
    workplace_commune_code,
    rome_code,
    rome_name,
    rome_job_title_name,
    company_name,
    company_description,
    company_logo_url,
    company_url,
    is_adapted_company,
    contract_type_code,
    contract_type_name,
    contract_nature_name,
    experience_requirement_code,
    experience_name,
    experience_comment,
    salary_name,
    salary_comment,
    salary_complement_1,
    salary_complement_2,
    working_hours_name,
    working_time_name,
    exercise_complement,
    exercise_condition,
    is_work_study,
    contact_name,
    contact_address_1,
    contact_address_2,
    contact_address_3,
    contact_phone,
    contact_email,
    contact_comment,
    recruiter_url,
    application_url,
    agency_phone,
    agency_email,
    position_count,
    is_disability_accessible,
    travel_code,
    travel_name,
    qualification_code,
    qualification_name,
    naf_code,
    sector_code,
    sector_name,
    company_size_name,
    offer_origin_code,
    offer_origin_name,
    offer_origin_url,
    is_lacking_candidates,
    is_adapted_employer,
    is_disability_committed_employer
) as
    select
        -- Ordre de l'API (pertinence), conservé par le chargement
        c.seq_id as search_rank,
        c.c001   as external_id,
        j.title,
        j.description,
        j.created_at,
        j.updated_at,
        j.workplace_name,
        j.workplace_latitude,
        j.workplace_longitude,
        j.workplace_postal_code,
        j.workplace_commune_code,
        j.rome_code,
        j.rome_name,
        j.rome_job_title_name,
        j.company_name,
        j.company_description,
        j.company_logo_url,
        j.company_url,
        j.is_adapted_company,
        j.contract_type_code,
        j.contract_type_name,
        j.contract_nature_name,
        j.experience_requirement_code,
        j.experience_name,
        j.experience_comment,
        j.salary_name,
        j.salary_comment,
        j.salary_complement_1,
        j.salary_complement_2,
        j.working_hours_name,
        j.working_time_name,
        j.exercise_complement,
        j.exercise_condition,
        j.is_work_study,
        j.contact_name,
        j.contact_address_1,
        j.contact_address_2,
        j.contact_address_3,
        j.contact_phone,
        j.contact_email,
        j.contact_comment,
        j.recruiter_url,
        j.application_url,
        j.agency_phone,
        j.agency_email,
        j.position_count,
        j.is_disability_accessible,
        j.travel_code,
        j.travel_name,
        j.qualification_code,
        j.qualification_name,
        j.naf_code,
        j.sector_code,
        j.sector_name,
        j.company_size_name,
        j.offer_origin_code,
        -- null pour un code absent du référentiel
        o.offer_origin_name,
        j.offer_origin_url,
        j.is_lacking_candidates,
        j.is_adapted_employer,
        j.is_disability_committed_employer
    from
        apex_collections            c
        cross apply
            json_table ( c.clob001, '$'
                columns (
                    title varchar2 ( 4000 char ) truncate path '$.intitule',
                    description clob path '$.description',
                    created_at timestamp with time zone path '$.dateCreation',
                    updated_at timestamp with time zone path '$.dateActualisation',
                    workplace_name varchar2 ( 4000 char ) truncate path '$.lieuTravail.libelle',
                    workplace_latitude number path '$.lieuTravail.latitude',
                    workplace_longitude number path '$.lieuTravail.longitude',
                    workplace_postal_code varchar2 ( 4000 char ) truncate path '$.lieuTravail.codePostal',
                    workplace_commune_code varchar2 ( 4000 char ) truncate path '$.lieuTravail.commune',
                    rome_code varchar2 ( 4000 char ) truncate path '$.romeCode',
                    rome_name varchar2 ( 4000 char ) truncate path '$.romeLibelle',
                    rome_job_title_name varchar2 ( 4000 char ) truncate path '$.appellationlibelle',
                    company_name varchar2 ( 4000 char ) truncate path '$.entreprise.nom',
                    company_description clob path '$.entreprise.description',
                    company_logo_url varchar2 ( 4000 char ) truncate path '$.entreprise.logo',
                    company_url varchar2 ( 4000 char ) truncate path '$.entreprise.url',
                    -- Statut d'entreprise adaptée (entreprise.entrepriseAdaptee)
                    is_adapted_company boolean path '$.entreprise.entrepriseAdaptee',
                    contract_type_code varchar2 ( 4000 char ) truncate path '$.typeContrat',
                    contract_type_name varchar2 ( 4000 char ) truncate path '$.typeContratLibelle',
                    contract_nature_name varchar2 ( 4000 char ) truncate path '$.natureContrat',
                    -- D débutant accepté, E exigée, S souhaitée
                    experience_requirement_code varchar2 ( 4000 char ) truncate path '$.experienceExige',
                    experience_name varchar2 ( 4000 char ) truncate path '$.experienceLibelle',
                    experience_comment varchar2 ( 4000 char ) truncate path '$.experienceCommentaire',
                    salary_name varchar2 ( 4000 char ) truncate path '$.salaire.libelle',
                    salary_comment varchar2 ( 4000 char ) truncate path '$.salaire.commentaire',
                    salary_complement_1 varchar2 ( 4000 char ) truncate path '$.salaire.complement1',
                    salary_complement_2 varchar2 ( 4000 char ) truncate path '$.salaire.complement2',
                    working_hours_name varchar2 ( 4000 char ) truncate path '$.dureeTravailLibelle',
                    -- Temps plein ou temps partiel
                    working_time_name varchar2 ( 4000 char ) truncate path '$.dureeTravailLibelleConverti',
                    exercise_complement varchar2 ( 4000 char ) truncate path '$.complementExercice',
                    exercise_condition varchar2 ( 4000 char ) truncate path '$.conditionExercice',
                    is_work_study boolean path '$.alternance',
                    contact_name varchar2 ( 4000 char ) truncate path '$.contact.nom',
                    contact_address_1 varchar2 ( 4000 char ) truncate path '$.contact.coordonnees1',
                    contact_address_2 varchar2 ( 4000 char ) truncate path '$.contact.coordonnees2',
                    contact_address_3 varchar2 ( 4000 char ) truncate path '$.contact.coordonnees3',
                    contact_phone varchar2 ( 4000 char ) truncate path '$.contact.telephone',
                    -- Plus d'adresse : une phrase avec le lien vers l'offre sur
                    -- francetravail.fr (de même pour agency_email)
                    contact_email varchar2 ( 4000 char ) truncate path '$.contact.courriel',
                    contact_comment varchar2 ( 4000 char ) truncate path '$.contact.commentaire',
                    recruiter_url varchar2 ( 4000 char ) truncate path '$.contact.urlRecruteur',
                    application_url varchar2 ( 4000 char ) truncate path '$.contact.urlPostulation',
                    agency_phone varchar2 ( 4000 char ) truncate path '$.agence.telephone',
                    agency_email varchar2 ( 4000 char ) truncate path '$.agence.courriel',
                    position_count number path '$.nombrePostes',
                    is_disability_accessible boolean path '$.accessibleTH',
                    travel_code varchar2 ( 4000 char ) truncate path '$.deplacementCode',
                    travel_name varchar2 ( 4000 char ) truncate path '$.deplacementLibelle',
                    qualification_code varchar2 ( 4000 char ) truncate path '$.qualificationCode',
                    qualification_name varchar2 ( 4000 char ) truncate path '$.qualificationLibelle',
                    naf_code varchar2 ( 4000 char ) truncate path '$.codeNAF',
                    -- Division NAF : deux premiers chiffres du code NAF
                    sector_code varchar2 ( 4000 char ) truncate path '$.secteurActivite',
                    sector_name varchar2 ( 4000 char ) truncate path '$.secteurActiviteLibelle',
                    company_size_name varchar2 ( 4000 char ) truncate path '$.trancheEffectifEtab',
                    -- 1 France Travail, 2 partenaire
                    offer_origin_code varchar2 ( 4000 char ) truncate path '$.origineOffre.origine',
                    offer_origin_url varchar2 ( 4000 char ) truncate path '$.origineOffre.urlOrigine',
                    is_lacking_candidates boolean path '$.offresManqueCandidats',
                    -- Conditions adaptées à un travailleur handicapé
                    -- (entrepriseAdaptee à la racine, distinct de is_adapted_company)
                    is_adapted_employer boolean path '$.entrepriseAdaptee',
                    is_disability_committed_employer boolean path '$.employeurHandiEngage'
                )
            )
        j
        left join jobtracker.ft_offer_origins o on o.offer_origin_code = j.offer_origin_code
    where
        -- Nom de ft_offer_search.co_collection_name, en dur : une vue ne peut
        -- pas lire une constante de package ; l'écart est détecté par les tests
        c.collection_name = 'FT_OFFER_SEARCH'
with read only;

